def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c

    if total_opp_c == 0:
        return 'D' if n >= 3 else 'C'
    if total_opp_d == 0:
        return 'C'

    W = min(n, 15)
    recent = history[-W:]
    recent_opp_c = sum(1 for a, b in recent if b == 'C')
    recent_opp_d = W - recent_opp_c

    c_trans = 0
    c_to_c = 0
    d_trans = 0
    d_to_c = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            d_trans += 1
            if history[i + 1][1] == 'C':
                d_to_c += 1
        else:
            c_trans += 1
            if history[i + 1][1] == 'C':
                c_to_c += 1

    qC = (c_to_c + 3.0) / (c_trans + 4.0)
    qD = (d_to_c + 2.0) / (d_trans + 4.0)

    rstart = max(0, n - 15)
    rc_trans = 0
    rc_to_c = 0
    rd_trans = 0
    rd_to_c = 0
    for i in range(rstart, n - 1):
        if history[i][0] == 'D':
            rd_trans += 1
            if history[i + 1][1] == 'C':
                rd_to_c += 1
        else:
            rc_trans += 1
            if history[i + 1][1] == 'C':
                rc_to_c += 1

    if rc_trans >= 4:
        qC = (qC + 2.0 * ((rc_to_c + 3.0) / (rc_trans + 4.0))) / 3.0
    if rd_trans >= 4:
        qD = (qD + 2.0 * ((rd_to_c + 2.0) / (rd_trans + 4.0))) / 3.0

    unpunished = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'C':
            unpunished += 1
        else:
            break

    unprovoked = 0
    for a, b in reversed(history):
        if a == 'C' and b == 'D':
            unprovoked += 1
        else:
            break

    mutual_d = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            mutual_d += 1
        else:
            break

    if unpunished >= 2 or (unpunished == 1 and qD >= 0.60 and d_trans >= 1 and (recent_opp_c >= W - 2 or total_opp_c * 10 >= n * 8)):
        return 'D'

    if unprovoked >= 7 or (unprovoked >= 3 and qC <= 0.60) or qC <= 0.42:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if qD >= 0.60 and d_trans >= 1:
                return 'D'
            if mutual_d >= 5:
                return 'D'
            if qC > 0.55:
                return 'C'
            return 'D'

        rate = total_opp_c / float(n)
        if unprovoked <= 3 and rate >= 0.70 and qC > 0.65:
            return 'C'
        if total_opp_d * 100 >= n * 35:
            return 'D'
        if qD >= 0.60 or qC <= 0.55:
            return 'D'
        return 'C'

    if my_last == 'D':
        if unpunished >= 2 or (qD >= 0.60 and d_trans >= 1):
            return 'D'
        if recent_opp_d >= 7:
            return 'D'
        return 'C'

    if qD >= 0.62:
        return 'D'
    if qD >= 0.60 and (recent_opp_c >= W - 4 or total_opp_c * 10 >= n * 8):
        return 'D'
    if recent_opp_d >= 7:
        return 'D'

    rate = total_opp_c / float(n)
    if rate < 0.45:
        return 'D'

    if rate < 0.65:
        if recent_opp_d >= 7 or qD >= 0.55:
            return 'D'
        if qD >= 0.48 and rng.random() < 0.15:
            return 'D'
        return 'C'

    if rate < 0.80:
        if recent_opp_c >= W - 4 and qD >= 0.48 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if recent_opp_c >= W - 3 and qD >= 0.48 and rng.random() < 0.07:
        return 'D'

    return 'C'
